const vec2 modran = vec2 (q15,q16);
const vec2 hor = (vec2(1.0)/uTexSize)*vec2 ( 1.0 , 0.0 ),ver = (vec2(1.0)/uTexSize)*vec2 ( 0.0 , 1.0 );
const vec3 mov = vec3 (q10,q11, 0.0 );
vec2 noise2 (vec2 uvi, float h) {vec2 tmp = 0; float s = 1;
for (int n = 1; n <= 3; n +=1 ) {tmp += texture(sampler_noise_mq,(uvi)*s+uTime*0.003)/s; s*= 3+h*-0.0;}
return sat (abs(tmp * -1.0)-0.2);}
vec3 rs_lav (vec2 uvi, float berg) {  float z; vec2 rs;
z = 1.0 / (uvi.y+hory)*(alti-berg * 16.0);
z = 1.0 / (uvi.y+hory)*(alti-berg*z*q18);
rs.x = uvi.x * 1.25*uAspect.x/uAspect.y*z ; rs.y = z;
return vec3(rs*xyscale,z)+mov * 1.0; }

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv0 = uv;
rsl = rs_lav (uv-0.5,-GetBlur1(uv).b+modran.yx);
mod = texture(sampler_noise_mq, rsl*0.1)*1.5;
ret0 = GetPixel(uv);
dist = ret0.g;
struc = ret0.r;
height = 1.0 - ret0.b;
snow = abs (height-GetBlur1(uv).b)* (2.0 * height*(0.0+struc))/dist * 1.0;
ret = ret0;;
ret0.g *= ret0.g;
ret = mix(ret0,GetBlur1(uv),sat(1-3*ret0.g-ret0.b)) ;
ret.b = pow (ret0.b, 3.0 ) / 2.0 + ret.r / 2.0;
ret.g = pow (ret0.g,1.2) / 2.0+ ret.r / 4.0;
ret.rg = sat (ret.rg+lum(ret) / 2.0) + ret.b*(mod.z-0.3)*0.5;
//wolken
rsl = rs_lav (uv-0.5, -sat(GetBlur1(uv).b*0.7));
ret += noise2(3.0 * rsl,GetBlur1(uv).b).x * clamp01(4.0 * ret0.b - 3.0) / abs(rsl.z)*1.5*mod.y;
//Sonne
ret += (dist*dist / 8.0) ;
  fragColor = vec4(ret, 1.0);
}

